import * as E from './engine.js';
import {icon,enemyArt} from './icons.js';
const $=s=>document.querySelector(s),h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let visitTotal=null;
let data,run=null,records=[],sound=false,audioCtx,filter='全部',query='',modalReturn=null;
const themes=['#df725e','#8cc39e','#bca3db','#e6ac64','#e0bc61','#7fb7d6','#b0c779','#c99c78','#bca7e9','#7caac4'];
const marks=['flame','blade','drop','spark','sun','dice','orbit','eye','shield','node'];
const modeName=m=>m==='choice'?'三选一':'随机授予';
function read(k,fallback){try{return JSON.parse(localStorage.getItem(k))??fallback;}catch{return fallback;}}
function write(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true;}catch{toast('浏览器未能保存数据。请及时导出记录。');return false;}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function route(){return (location.hash.slice(1)||'/').split('?')[0];}
function nav(active){return `<header class="site-header"><a class="brand" href="#/" aria-label="重构，返回首页"><span class="brand-symbol">${icon('cube')}</span><span>重构<span class="brand-en">ROGUE LAB</span></span></a><nav aria-label="主导航"><a class="${active==='home'?'active':''}" href="#/">实验室</a><a class="${active==='atlas'?'active':''}" href="#/atlas">游戏图鉴<span class="nav-count">10</span></a><a class="${active==='research'?'active':''}" href="#/research">研究档案</a></nav><a class="button button-small nav-play" href="#/game">${icon('spark')} 开始一局</a></header>`;}
function footer(){return `<footer class="site-footer"><div class="footer-brand">${icon('cube')} 重构 <span>ROGUE LAB</span></div><p>理解随机，练习选择。一个关于肉鸽游戏的互动研究项目。</p><div><a href="#/research">项目与资料来源</a><button class="text-button" data-act="credits">制作说明</button><span>© 2026 ROGUE LAB</span></div><p class="visit-counter">${icon('eye')} 浏览计数 <span data-visit-total>${visitTotal===null?'连接中':visitTotal===false?'暂不可用':visitTotal.toLocaleString('zh-CN')}</span></p></footer>`;}
function art(g,i=0){return `<div class="game-art art-${h(g.id)}" style="--art:${themes[i%10]}"><div class="art-grid"></div><div class="art-orbit"></div><span class="art-mark">${icon(marks[i%10])}</span><span class="art-mini">MECHANICS STUDY</span><span class="art-word">${h(g.titleEn.toUpperCase())}</span></div>`;}
function gameTile(g,i){return `<a class="game-tile" href="#/atlas/${h(g.id)}">${art(g,i)}<div class="tile-meta"><span class="eyebrow">${h(g.genre)}</span><span class="mono">${g.year}</span></div><h3>${h(g.name)}</h3><p>${h(g.hook)}</p><span class="tile-tags">${g.tags.slice(0,3).map(x=>`<span>${h(x)}</span>`).join('')}</span></a>`;}
function renderHome(){return `${nav('home')}<main id="main"><section class="hero section-shell"><div class="hero-copy"><span class="eyebrow"><span class="live-dot"></span> AN INTERACTIVE ROGUELIKE LAB</span><h1>随机之中，<br><span>自有选择。</span></h1><p class="hero-desc">为什么失败之后，还想再来一局？<br>从十款经典，到一场亲手参与的卡牌实验，<br class="desktop-only">探索肉鸽游戏里的随机、策略与可能。</p><div class="hero-actions"><a class="button" href="#/game">${icon('spark')} 试玩《余烬协议》</a><a class="button button-ghost" href="#/atlas">探索游戏图鉴</a></div><div class="hero-note"><span>${icon('clock')} 单局约 5–10 分钟</span><span>${icon('check')} 免费 · 浏览器即玩</span></div></div><div class="hero-visual" aria-label="余烬协议原创卡牌机制示意"><div class="visual-grid"></div><div class="orbital orbital-one"></div><div class="orbital orbital-two"></div><span class="visual-label mono">PROJECT EMBER / V.1.0</span><div class="floating-card float-left"><span class="mini-cost">1</span><div class="card-art">${icon('shield')}</div><b>相位盾</b><small>防御 · 稳住局面</small></div><div class="floating-card float-right"><span class="mini-cost">1</span><div class="card-art">${icon('drop')}</div><b>腐蚀协议</b><small>策略 · 累积优势</small></div><div class="floating-card float-center"><span class="mini-cost">1</span><span class="mini-card-label">ATTACK / EMBER</span><div class="card-art">${icon('flame')}</div><b>余烬</b><small>每一次出手，都留下力量。</small><span class="card-rule">伤害 7 <span>力量 +1</span></span></div><span class="visual-caption">SAME SEED. DIFFERENT CHOICES.</span><span class="coordinate mono">RANDOMNESS × AGENCY</span></div></section><section class="portal-section section-shell"><div class="section-heading"><div><span class="eyebrow">TWO WAYS TO EXPLORE</span><h2>先理解，再亲自改变。</h2></div><p>同一个世界，两种进入方式。</p></div><div class="portal-grid"><a class="portal play-portal" href="#/game"><span class="portal-icon">${icon('spark')}</span><div><span class="eyebrow">PLAY THE EXPERIMENT</span><h3>余烬协议</h3><p>穿过七个节点，构筑你的牌组。<br>让相同的起点，走向不同的结局。</p><span class="portal-link">进入卡牌实验 ${icon('blade')}</span></div><span class="portal-background">${icon('flame')}</span></a><a class="portal atlas-portal" href="#/atlas"><span class="portal-icon">${icon('book')}</span><div><span class="eyebrow">EXPLORE THE GENRE</span><h3>肉鸽游戏图鉴</h3><p>十款作品，十种对“重来”的回答。<br>看懂随机背后的设计语言。</p><span class="portal-link">打开游戏图鉴 ${icon('book')}</span></div><span class="portal-background">${icon('orbit')}</span></a></div></section><section class="loop-section section-shell"><div class="section-heading"><div><span class="eyebrow">THE ROGUE LOOP</span><h2>一局结束，探索才刚开始。</h2></div><p>“肉鸽”是 Roguelike 的音译。<br>现代作品常把这套循环与不同玩法融合。</p></div><div class="loop-grid">${[['dice','随机起点','变化的关卡、道具与遭遇，让经验无法替代所有判断。'],['node','局内选择','根据眼前的选项，逐步搭出这一局独有的打法。'],['flame','失败与重启','本局进度重置；不同作品会保留不同的解锁或成长。'],['eye','带着理解回来','你逐渐学会规则、识别机会，下一次作出新的决定。']].map(([ic,t,p])=>`<article>${icon(ic)}<h3>${t}</h3><p>${p}</p></article>`).join('')}</div><p class="fine-print">这里使用中文日常语境中的广义“肉鸽”。严格的传统 Roguelike 与现代 Roguelite 并不完全相同。<a href="#/atlas">查看术语说明</a></p></section><section class="featured section-shell"><div class="section-heading"><div><span class="eyebrow">A GENRE, MANY POSSIBILITIES</span><h2>相同的循环，不同的世界。</h2></div><a class="text-link" href="#/atlas">查看全部 10 款作品</a></div><div class="games-grid featured-grid">${[0,1,5,9].map(i=>gameTile(data.games[i],i)).join('')}</div><p class="fine-print">图形为本站原创机制示意，非官方游戏封面。</p></section><section class="research-banner section-shell"><div>${icon('chart')}<span class="eyebrow">THE QUESTION BEHIND THE GAME</span><h2>运气越多，就越有趣吗？</h2><p>比较“随机授予”与“三选一”的奖励方式。<br>记录一次真实体验，让问题有机会被检验。</p></div><a class="button button-ghost" href="#/research">了解实验与项目</a></section></main>${footer()}`;}
function renderAtlas(){return `${nav('atlas')}<main id="main" class="section-shell atlas-page"><div class="page-intro"><span class="eyebrow">FIELD GUIDE / 10 GAMES</span><h1>十种方式，<span>重新开始。</span></h1><p>肉鸽并不是一种固定的战斗方式。它可以是一副卡牌、<br class="desktop-only">一次冥界逃离，也可以是一艘资源紧缺的飞船。</p></div><div class="atlas-toolbar"><div class="filter-tabs" role="group" aria-label="按玩法筛选">${['全部','卡牌','动作','射击','策略','探索'].map(t=>`<button class="filter ${filter===t?'active':''}" data-act="filter" data-filter="${t}" aria-pressed="${filter===t}">${t}</button>`).join('')}</div><label class="search-box">${icon('search')}<input id="game-search" type="search" placeholder="搜索游戏、玩法、机制" aria-label="搜索游戏" value="${h(query)}"></label></div><div id="atlas-results">${atlasResults()}</div><section class="glossary"><div class="section-heading"><div><span class="eyebrow">A SMALL DICTIONARY</span><h2>读懂肉鸽的四个关键词。</h2></div></div><div class="glossary-grid">${data.terms.map((t,i)=>`<details ${i===0?'open':''}><summary>${h(t.term)} ${icon('info')}</summary><span class="mono">${h(t.en)}</span><p>${h(t.description)}</p><a href="${h(t.sourceUrl)}" target="_blank" rel="noopener noreferrer">参考来源 ${icon('external')}</a></details>`).join('')}</div></section><aside class="editorial-note">${icon('info')}<p>${h(data.editorialNote)}<br>资料核查：${h(data.researchedAt)}。图形为原创机制示意，不是官方封面。作品名称与相关权利归各权利人所有。</p></aside></main>${footer()}`;}
function atlasResults(){const list=data.games.filter(g=>(filter==='全部'||g.tags.includes(filter)||g.genre.includes(filter))&&(!query||`${g.name} ${g.titleEn} ${g.genre} ${g.tags.join(' ')} ${g.description}`.toLowerCase().includes(query.toLowerCase())));return `<div class="results-count mono" aria-live="polite">${list.length} / 10 款作品</div><div class="games-grid">${list.length?list.map(g=>gameTile(g,data.games.indexOf(g))).join(''):'<div class="empty-state"><h3>暂时没有匹配的作品</h3><p>试试“卡牌”“射击”，或清空关键词。</p><button class="button button-ghost" data-act="reset-filter">重置筛选</button></div>'}</div>`;}
function renderDetail(id){const g=data.games.find(x=>x.id===id);if(!g)return renderNotFound();const i=data.games.indexOf(g);return `${nav('atlas')}<main id="main" class="section-shell detail-page"><a class="back-link" href="#/atlas">返回游戏图鉴</a><section class="detail-hero"><div class="detail-copy"><span class="eyebrow">${h(g.genre)} / ${g.year}</span><h1>${h(g.name)}</h1><span class="detail-en">${h(g.titleEn)}</span><p class="detail-hook">${h(g.hook)}</p><p>${h(g.description)}</p><div class="detail-tags">${g.tags.map(t=>`<span>${h(t)}</span>`).join('')}</div><a class="button button-ghost" href="${h(g.sourceUrl)}" target="_blank" rel="noopener noreferrer">访问官方商店 ${icon('external')}</a></div>${art(g,i)}</section><section class="detail-bottom"><article><span class="eyebrow">HOW IT WORKS</span><h2>核心机制</h2><ul class="mechanic-list">${g.mechanics.map(x=>`<li>${icon('node')}${h(x)}</li>`).join('')}</ul></article><article class="design-note"><span class="eyebrow">DESIGN OBSERVATION</span><h2>从中学到什么？</h2><p>${h(g.lesson.replace('设计观察：',''))}</p><small>这是本项目的设计解读，不是经实验验证的结论。</small></article></section><div class="source-line"><p>开发者：${h(g.developer)} · PC 正式发行：${g.year} 年</p><p>资料来源：<a href="${h(g.sourceUrl)}" target="_blank" rel="noopener noreferrer">${h(g.sourceLabel)}</a> · 核查于 ${data.researchedAt}</p><p>图形为本站原创机制示意，非官方封面。</p></div><section class="next-game"><span class="eyebrow">KEEP EXPLORING</span><h2>下一个世界</h2><a href="#/atlas/${data.games[(i+1)%10].id}">${h(data.games[(i+1)%10].name)} <span>${h(data.games[(i+1)%10].genre)}</span></a></section></main>${footer()}`;}
function renderGameStart(){return `${nav('game')}<main id="main" class="game-start section-shell"><div class="game-pitch"><span class="eyebrow">AN ORIGINAL DECKBUILDING ROGUELITE</span><h1>余烬协议<span>EMBER PROTOCOL</span></h1><p class="game-tagline">世界失序之后，<br>你仍然拥有选择。</p><p>作为最后一名信号修复者，穿过七个节点，<br>在战斗与遭遇中构筑牌组，重启失序核心。</p><div class="start-art">${enemyArt('boss')}</div><div class="pitch-facts"><span>${icon('clock')} 5–10 分钟</span><span>${icon('book')} 21 种卡牌</span><span>${icon('node')} 7 个节点</span></div></div><section class="setup-panel"><span class="eyebrow">SET UP YOUR RUN</span><h2>这次，如何面对未知？</h2><p>两种模式只改变战斗后的卡牌奖励方式。</p>${run&&run.phase!=='ended'?`<div class="resume-panel"><span>检测到未完成的旅程 · 节点 ${run.stage+1}/7</span><button class="button" data-act="resume">继续旅程</button></div>`:''}<form id="start-form"><fieldset><legend>奖励模式</legend><label class="mode-option"><input type="radio" name="mode" value="choice" checked><span class="mode-icon">${icon('node')}</span><span><b>三选一</b><small>从三个随机奖励中，挑选最适合牌组的一个。</small></span></label><label class="mode-option"><input type="radio" name="mode" value="random"><span class="mode-icon">${icon('dice')}</span><span><b>随机授予</b><small>系统随机授予一张卡牌，尝试适应得到的结果。</small></span></label></fieldset><label class="seed-label" for="seed-input">世界种子 <span>相同起点，便于比较</span></label><div class="seed-row"><input id="seed-input" name="seed" maxlength="48" value="EMBER-01" autocomplete="off" required><button class="icon-button" type="button" data-act="new-seed" aria-label="生成新种子">${icon('dice')}</button></div><p class="fine-print">同一种子对应相同遭遇、初始洗牌和奖励候选。你的选择仍会影响后续抽牌与结果。</p><button class="button start-button" type="submit">${icon('spark')} 启动余烬协议</button></form><div class="setup-links"><button class="text-button" data-act="guide">玩法说明</button><button class="text-button" data-act="library">查看全部卡牌</button><a href="#/research">实验说明</a></div><p class="local-note">${icon('shield')} 无需账号。进度与实验记录仅保存在当前浏览器，可自行导出。</p></section></main>${footer()}`;}
function card(c,{action='',index=0,disabled=false,small=false}={}){const d=E.cardData(c),tag=action?'button':'div';return `<${tag} ${action?`type="button" data-act="${action}" data-index="${index}" ${disabled?'disabled':''}`:''} class="playing-card ${d.type} ${c.up?'upgraded':''} ${small?'small-card':''}" ${action?`aria-label="${h(d.name)}${c.up?'强化':''}，${d.cost}能量，${h(E.cardText(c))}"`:''}><span class="energy-cost">${d.cost}</span><span class="card-type">${d.type==='attack'?'攻击':'技能'}${c.up?' · 强化':''}</span><span class="playing-card-art">${icon(d.icon)}</span><b>${h(d.name)}${c.up?'+':''}</b><span class="card-description">${h(E.cardText(c))}</span>${action==='play'?`<span class="card-key mono">${index<9?index+1:'点击出牌'}</span>`:''}</${tag}>`;}
function stageRail(){return `<aside class="run-rail"><div class="rail-heading"><span class="eyebrow">YOUR JOURNEY</span><h2>前往余烬之心</h2></div><ol>${E.STAGES.map((s,i)=>`<li class="${i===run.stage?'current':i<run.stage?'passed':''}"><span class="stage-icon">${icon(i<run.stage?'check':s.type==='camp'?'tent':s.type==='event'?'eye':i===6?'sun':'blade')}</span><div><b>${h(s.name)}</b><small>${s.type==='battle'?(i===6?'最终核心':i===4?'精英战斗':'战斗'):s.type==='camp'?'休息 / 强化':'事件抉择'}</small></div>${i===run.stage?'<span class="stage-here">当前</span>':''}</li>`).join('')}</ol><div class="relic-list"><span class="eyebrow">RELICS</span><p>${icon('spark')}<span>余烬核心<small>每场战斗首回合多 1 能量</small></span></p>${run.relics.includes('seal')?`<p>${icon('flame')}<span>焚心印记<small>战斗胜利回复 4 点生命</small></span></p>`:''}</div><button class="text-button" data-act="view-deck">查看牌组 · ${run.deck.length} 张</button><span class="game-visit">浏览计数 <span data-visit-total>${typeof visitTotal==='number'?visitTotal.toLocaleString('zh-CN'):'—'}</span></span></aside>`;}
function playerBar(){return `<div class="player-bar"><div class="player-avatar">${icon('flame')}</div><div class="player-health"><b>信号修复者 <span>${run.hp} / ${run.maxHp}</span></b><div class="health-track"><span style="width:${run.hp/run.maxHp*100}%"></span></div></div>${run.phase==='battle'?`<div class="combat-resource energy-resource">${icon('spark')}<strong>${run.energy}</strong><small>能量</small></div><div class="combat-resource">${icon('shield')}<strong>${run.block}</strong><small>护盾</small></div>${run.str?`<div class="combat-resource strength-resource">${icon('blade')}<strong>${run.str}</strong><small>力量</small></div>`:''}`:''}</div>`;}
function battleView(){const it=E.intent(run),n=it.type==='attack'?(it.value+run.enemy.str):it.value;return `<section class="battle-panel"><div class="battle-heading"><div><span class="eyebrow">ENCOUNTER ${run.stage+1} / 7</span><h1>${h(E.STAGES[run.stage].name)}</h1></div><span class="turn-chip mono">TURN ${String(run.turn).padStart(2,'0')}</span></div><div class="arena"><div class="arena-grid"></div><div class="enemy-intent ${it.type==='attack'?'danger':''}">${icon(it.type==='attack'?'blade':it.type==='guard'?'shield':'spark')}<span>下回合：${it.type==='attack'?`攻击 ${n}${it.hits?` × ${it.hits}`:''}`:it.type==='guard'?`护盾 +${n}`:`力量 +${n}`}</span></div><div class="enemy-figure">${enemyArt(run.enemy.art)}</div><div class="enemy-status"><h2>${h(run.enemy.name)} ${run.enemy.block?`<span>${icon('shield')}${run.enemy.block}</span>`:''}</h2><div class="enemy-hp"><span style="width:${run.enemy.hp/run.enemy.maxHp*100}%"></span><b>${run.enemy.hp} / ${run.enemy.maxHp}</b></div><div class="status-effects">${run.enemy.poison?`<span>${icon('drop')}腐蚀 ${run.enemy.poison}</span>`:''}${run.enemy.vulnerable?`<span>${icon('blade')}易伤 ${run.enemy.vulnerable}</span>`:''}${run.enemy.str?`<span>力量 +${run.enemy.str}</span>`:''}</div></div></div>${playerBar()}<div class="hand-heading"><span>手牌 <span class="mono">${run.hand.length} / 10</span></span><span class="fine-print">点击出牌，或按数字 1–9</span><button class="text-button" data-act="piles">抽牌 ${run.draw.length} · 弃牌 ${run.discard.length}</button></div><div class="hand-cards" aria-label="手牌">${run.hand.length?run.hand.map((c,i)=>card(c,{action:'play',index:i,disabled:E.cardData(c).cost>run.energy})).join(''):'<div class="empty-hand">手牌已用完，结束回合以抽取新牌。</div>'}</div><div class="battle-bottom"><span>${icon('info')} 每回合能量与护盾重置，抽 5 张牌。</span><button class="button" data-act="end-turn">结束回合 <kbd>空格</kbd></button></div></section>`;}
function rewardView(){return `<section class="interlude-panel"><span class="eyebrow">BATTLE COMPLETE</span><div class="interlude-symbol">${icon('check')}</div><h1>胜利，留下新的可能。</h1><p>${run.mode==='choice'?'选择一张卡牌加入牌组。什么能让你的策略更完整？':'这是世界为你留下的奖励。如何让它融入现有牌组？'}</p><span class="mode-badge">${icon(run.mode==='choice'?'node':'dice')}${modeName(run.mode)}</span><div class="reward-cards">${(run.mode==='choice'?run.offers:run.offers.slice(0,1)).map((c,i)=>card(c,{action:'reward',index:i})).join('')}</div><p class="fine-print">${run.mode==='choice'?'点击卡牌，将它加入牌组。':'随机授予模式：点击收下本次随机获得的卡牌。'}${run.stage===4?' 已获得遗物「焚心印记」。':''}</p>${playerBar()}</section>`;}
function travelView(){return `<section class="interlude-panel travel-panel"><span class="eyebrow">SIGNAL RESTORED</span><div class="interlude-symbol">${icon('node')}</div><h1>信号已接通。</h1><p>下一站：${h(E.STAGES[run.stage+1]?.name||'旅程终点')}。<br>带上这次选择，继续向核心前进。</p><button class="button" data-act="advance">继续旅程</button>${playerBar()}</section>`;}
function eventView(){const first=run.stage===1;return `<section class="interlude-panel event-panel"><span class="eyebrow">A MOMENT OF CHOICE</span><div class="interlude-symbol">${icon('eye')}</div><h1>${first?'失落缓存':'最后的信号'}</h1><p class="event-story">${first?'废弃终端闪烁着微弱的光。你找到了修复组件，和一份仍可读取的攻击协议。能源只够启动其中一个。':'核心近在眼前。一台旧式维修机发出最后的呼叫：它能修复你的损伤，也能帮你卸下不再需要的负担。'}</p><div class="event-choices"><button data-act="event-repair"><span>${icon('heart')}</span><b>${first?'修复机体':'接受修复'}</b><small>回复 ${first?10:14} 点生命</small></button><button data-act="${first?'event-risk':'event-remove'}"><span>${icon(first?'flame':'book')}</span><b>${first?'读取余烬协议':'精简牌组'}</b><small>${first?'失去 5 点生命，获得「余烬」卡牌':'移除牌组中的一张卡牌'}</small></button></div>${playerBar()}</section>`;}
function campView(){return `<section class="interlude-panel"><span class="eyebrow">A QUIET INTERMISSION</span><div class="interlude-symbol">${icon('tent')}</div><h1>暂时，让火光停留。</h1><p>中继营地的防护还在运转。<br>休息修复，或为接下来的战斗强化一张卡牌。</p><div class="event-choices"><button data-act="rest"><span>${icon('heart')}</span><b>休息</b><small>回复 22 点生命</small></button><button data-act="upgrade"><span>${icon('spark')}</span><b>强化</b><small>永久强化本局牌组中的一张牌</small></button></div>${playerBar()}</section>`;}
function endedView(){const win=run.result==='win';return `<section class="interlude-panel result-panel"><span class="eyebrow">${win?'PROTOCOL COMPLETE':run.result==='abandoned'?'RUN ARCHIVED':'SIGNAL LOST'}</span><div class="interlude-symbol ${win?'':'loss'}">${icon(win?'sun':'flame')}</div><h1>${win?'余烬，重新点亮。':run.result==='abandoned'?'旅程已存档。':'这次重来，并非徒劳。'}</h1><p>${win?'失序核心已重启。这副由选择构成的牌组，带你走到了这里。':'记住这次遇到的困难，下一次试着作出不同选择。'}</p><div class="result-stats"><div><b>${run.stage+1}<small>/ 7</small></b><span>抵达节点</span></div><div><b>${run.stats.cardsPlayed}</b><span>使用卡牌</span></div><div><b>${run.stats.turns}</b><span>战斗回合</span></div><div><b>${Math.max(1,Math.round(run.durationMs/60000))}<small>分钟</small></b><span>本次用时</span></div></div><div class="result-mode mono">${h(run.seed)} · ${modeName(run.mode)}</div>${ratingForm()}<div class="result-actions"><button class="button" data-act="replay-other">同种子，试试${run.mode==='choice'?'随机授予':'三选一'}</button><button class="button button-ghost" data-act="new-game">重新出发</button><a class="text-link" href="#/research">查看实验记录</a></div></section>`;}
function ratingForm(){return run.rating?`<div class="rating-saved">${icon('check')} 已保存本次体验反馈，可在研究档案中导出。</div>`:`<form id="rating-form" class="rating-form"><b>这一局，你的感受如何？</b><p>自愿填写，仅本机保存。1 代表很低，5 代表很高。</p>${[['fairness','公平感'],['agency','选择感'],['enjoyment','乐趣']].map(([key,label])=>`<fieldset><legend>${label}</legend><div>${[1,2,3,4,5].map(n=>`<label><input type="radio" name="${key}" value="${n}" required><span>${n}</span></label>`).join('')}</div></fieldset>`).join('')}<button class="button button-small button-ghost" type="submit">保存体验反馈</button></form>`;}
function logPanel(){return `<aside class="battle-log"><span class="eyebrow">LIVE TRANSMISSION</span><h2>战斗记录</h2><div class="log-entries" aria-live="polite">${run.log.slice(-7).reverse().map((x,i)=>`<p class="${h(x.kind)} ${i===0?'latest':''}">${h(x.text)}</p>`).join('')||'<p>信号稳定，旅程继续。</p>'}</div><div class="hint-box">${icon('info')}<p>先看敌人意图，再决定如何分配能量。护盾会在下个己方回合开始时清空。</p></div></aside>`;}
function renderRun(){return `<header class="game-header"><a class="brand" href="#/">${icon('cube')}<span>余烬协议<span class="brand-en">EMBER PROTOCOL</span></span></a><div class="run-meta"><span class="mode-badge">${modeName(run.mode)}</span><span class="mono">${h(run.seed)}</span></div><div class="game-tools"><button class="icon-button" data-act="sound" aria-label="${sound?'关闭':'开启'}音效">${icon(sound?'volume':'mute')}</button><button class="icon-button" data-act="guide" aria-label="玩法说明">${icon('info')}</button><a class="text-link" href="#/game">返回</a></div></header><main id="main" class="game-shell ${run.phase==='ended'?'ended-shell':''}">${stageRail()}${run.phase==='battle'?battleView():run.phase==='reward'?rewardView():run.phase==='travel'?travelView():run.phase==='event'?eventView():run.phase==='camp'?campView():endedView()}${run.phase==='battle'?logPanel():''}</main>`;}
function mean(a){return a.length?a.reduce((s,n)=>s+n,0)/a.length:null;}
function recordsSummary(){const done=records.filter(r=>['win','loss'].includes(r.result));return `<div class="research-summary"><div><b>${done.length}</b><span>本机已完成局数</span></div><div><b>${done.filter(r=>r.mode==='choice').length}</b><span>三选一模式</span></div><div><b>${done.filter(r=>r.mode==='random').length}</b><span>随机授予模式</span></div><div><b>${done.filter(r=>r.rating).length}</b><span>已填写体验反馈</span></div></div>${done.length?`<div class="comparison-chart"><div class="section-heading"><h3>本机体验反馈</h3><span class="fine-print">1–5 分 · 仅统计已填写反馈的完成局</span></div>${[['agency','选择感'],['fairness','公平感'],['enjoyment','乐趣']].map(([key,label])=>`<div class="chart-row"><b>${label}</b><div>${['choice','random'].map(mode=>{const list=done.filter(r=>r.mode===mode&&r.rating).map(r=>r.rating[key]),avg=mean(list);return `<div class="chart-series ${mode}"><span>${modeName(mode)}</span><div class="chart-track"><span style="width:${avg?avg/5*100:0}%"></span></div><strong>${avg?avg.toFixed(1):'—'}</strong><small>n=${list.length}</small></div>`;}).join('')}</div></div>`).join('')}</div>`:'<div class="empty-state research-empty">'+icon('chart')+'<h3>你的第一局，就是第一条真实记录。</h3><p>这里还没有数据。完成游戏并填写反馈后，将显示两种模式的描述性对比。</p><a class="button button-ghost" href="#/game">开始第一局</a></div>'}`;}
function renderResearch(){return `${nav('research')}<main id="main" class="section-shell research-page"><div class="page-intro"><span class="eyebrow">RESEARCH FILE / PROJECT EMBER</span><h1>把“再来一局”，<br>变成一个<span>可探索的问题。</span></h1><p>一个原创游戏，一组可比较的机制，<br>以及从真实体验出发的设计记录。</p></div><section class="research-question"><span class="eyebrow">RESEARCH QUESTION</span><h2>奖励选择权，会怎样影响<br>玩家的选择感、公平感与乐趣？</h2><p>我们不预设“三选一一定更好”。《余烬协议》提供两个可玩的版本，让玩家亲自体验，然后记录感受与表现。</p><div class="conditions"><article>${icon('dice')}<h3>随机授予</h3><p>从同一奖励候选序列中，授予第一张随机卡牌，玩家负责适应。</p></article><span class="conditions-vs mono">VS</span><article>${icon('node')}<h3>三选一</h3><p>显示三张随机候选卡牌，由玩家选择其中一张加入牌组。</p></article></div></section><section class="method-section"><div class="section-heading"><div><span class="eyebrow">METHOD & LIMITS</span><h2>怎样比较，才说得清楚？</h2></div></div><div class="method-grid"><article><h3>控制共同起点</h3><p>使用相同种子、初始牌组、敌人顺序与奖励候选。战斗随机序列按节点独立生成；选牌和出牌仍会改变后续状态。</p></article><article><h3>记录行为与反馈</h3><p>记录模式、种子、胜负、回合、出牌与奖励选择。结束后可自愿填写 1–5 分的公平感、选择感和乐趣评分。</p></article><article><h3>平衡体验顺序</h3><p>正式试玩时，让部分参与者先玩随机授予，另一部分先玩三选一，减少熟练度与体验顺序的影响。</p></article><article><h3>承认结论边界</h3><p>本机记录不等于独立玩家样本；自主选模式、事件选择、牌组变化和小样本都会影响结果。此处统计只描述记录，不能证明因果。</p></article></div></section><section class="local-records"><div class="section-heading"><div><span class="eyebrow">YOUR LOCAL OBSERVATIONS</span><h2>本机实验记录</h2></div><div class="record-tools"><button class="button button-small button-ghost" data-act="export-json">${icon('download')} JSON</button><button class="button button-small button-ghost" data-act="export-csv">${icon('download')} CSV</button></div></div>${recordsSummary()}${records.length?`<div class="records-table-wrap"><table><caption class="sr-only">本机游戏记录</caption><thead><tr><th>时间</th><th>模式 / 种子</th><th>结果</th><th>节点</th><th>回合</th><th>反馈</th></tr></thead><tbody>${records.slice().reverse().slice(0,20).map(r=>`<tr><td>${h(new Date(r.startedAt).toLocaleDateString('zh-CN'))}</td><td>${modeName(r.mode)}<small>${h(r.seed)}</small></td><td><span class="result-tag ${r.result}">${r.result==='win'?'通关':r.result==='loss'?'失败':'中止'}</span></td><td>${r.stage+1}/7</td><td>${r.stats.turns}</td><td>${r.rating?'已填写':'未填写'}</td></tr>`).join('')}</tbody></table></div>`:''}<div class="records-bottom"><span class="fine-print">仅当前浏览器 · 不采集姓名，不自动上传 · 最多保留最近 100 局</span><button class="text-button danger-text" data-act="clear-records">清除本机记录</button></div></section><section class="project-files"><div><span class="eyebrow">PROJECT DOCUMENTATION</span><h2>从作品到项目。</h2><p>记录问题、规则、方法与局限。保留真实的制作过程和 AI 协助说明。</p></div><div class="download-list"><a href="./project-guide.html" target="_blank">项目说明与展示提纲 ${icon('external')}</a><a href="./study-kit.html" target="_blank">试玩流程与记录模板 ${icon('external')}</a><button data-act="library">完整卡牌手册 ${icon('book')}</button></div></section><section class="sources-section"><span class="eyebrow">REFERENCES & ATTRIBUTION</span><h2>资料来源与制作说明</h2><p>图鉴玩法介绍依据下列官方商店资料原创转述；“设计观察”为本项目的解读。年份指所引商店的 PC 正式发行年份。图形与游戏代码为本项目制作。</p><div class="sources-grid">${data.games.map(g=>`<a href="${h(g.sourceUrl)}" target="_blank" rel="noopener noreferrer">${h(g.titleEn)} ${icon('external')}</a>`).join('')}</div><div class="academic-sources"><a href="https://aaai.org/papers/ws04-04-001-mda-a-formal-approach-to-game-design-and-game-research/" target="_blank" rel="noopener noreferrer">MDA: A Formal Approach to Game Design and Game Research · Hunicke 等，2004</a><a href="https://www.pcgbook.com/" target="_blank" rel="noopener noreferrer">Procedural Content Generation in Games · Shaker 等，2016</a><a href="https://www.roguebasin.com/index.php/Berlin_Interpretation" target="_blank" rel="noopener noreferrer">Berlin Interpretation · 2008 年开发者讨论记录</a></div><p class="fine-print">制作方式：使用 AI 协助进行资料整理、代码与界面制作及文档起草。申请者应据实际情况补充自己的选题、决策、测试与修改贡献，并遵守申请要求。资料核查于 ${data.researchedAt}。</p></section></main>${footer()}`;}
function renderNotFound(){return `${nav('')}<main id="main" class="empty-state section-shell"><h1>这条路线尚未接通。</h1><a class="button" href="#/">返回实验室</a></main>${footer()}`;}
function render(){const p=route();document.body.classList.toggle('in-game',p==='/game/play'&&!!run);$('#app').innerHTML=p==='/'?renderHome():p==='/atlas'?renderAtlas():p.startsWith('/atlas/')?renderDetail(p.split('/')[2]):p==='/research'?renderResearch():p==='/game/play'&&run?renderRun():p==='/game'||p==='/game/play'?renderGameStart():renderNotFound();document.title=(p.startsWith('/game')?'余烬协议':p.startsWith('/atlas')?'肉鸽游戏图鉴':p==='/research'?'研究档案':'随机之中，自有选择')+' · 重构 ROGUE LAB';}
function saveRun(){if(!run)return;write('rogue-run-v1',run);if(run.phase==='ended'){const i=records.findIndex(r=>r.id===run.id);if(i>=0)records[i]=structuredClone(run);else records.push(structuredClone(run));records=records.slice(-100);write('rogue-records-v1',records);}}
function update(){saveRun();render();}
function goRun(){if(route()==='/game/play')render();else location.hash='/game/play';}
function start(seed,mode){run=E.createRun({seed,mode});saveRun();goRun();beep(280);}
function beep(freq=440){if(!sound)return;try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.setValueAtTime(freq,audioCtx.currentTime);g.gain.setValueAtTime(.035,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.12);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+.13);}catch{}}
function openModal(title,body,wide=false){modalReturn=document.activeElement;$('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide-modal':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><div class="modal-heading"><h2 id="modal-title">${h(title)}</h2><button class="icon-button" data-act="close-modal" aria-label="关闭">${icon('close')}</button></div><div class="modal-body">${body}</div></section></div>`;document.body.classList.add('modal-open');$('.modal [data-act="close-modal"]').focus();}
function closeModal(){if(!$('#overlay').innerHTML)return;$('#overlay').innerHTML='';document.body.classList.remove('modal-open');if(modalReturn?.isConnected)modalReturn.focus();}
function guide(){openModal('如何玩《余烬协议》',`<div class="guide-content"><p>目标：穿过七个节点，击败最终的失序核心。生命归零，本局结束。</p><ol><li><b>看意图：</b>敌人头顶显示下一步行动。优先估算需要多少护盾。</li><li><b>分能量：</b>卡牌左上角是费用。每回合 3 能量，战斗首回合因遗物获得 4 能量。</li><li><b>点击出牌：</b>数字键 1–9 也可出对应手牌，空格结束回合。手牌最多 10 张。</li><li><b>回合交替：</b>结束回合会弃掉剩余手牌；敌人行动后，你的护盾清空、能量重置，再抽 5 张牌。敌人护盾在其行动前清空。</li><li><b>逐步构筑：</b>胜利后获得卡牌，营地可休息或强化。抽牌堆用完时自动洗入弃牌。</li></ol><h3>关键词</h3><p><b>消耗：</b>卡牌本场战斗不再回到抽牌堆，下场恢复。<br><b>力量：</b>本场每次攻击增加等量伤害。<br><b>腐蚀：</b>敌人行动前受到层数等量伤害，随后减少 1 层。无视护盾。<br><b>易伤：</b>受到攻击伤害 ×1.5，向下取整；每次敌方行动后减少 1 回合。</p><p class="fine-print">可以随时返回首页，当前旅程会自动保存。手机端可横向滑动手牌。系统减少动态效果设置会自动生效。</p></div>`);}
function picker(kind){const title=kind==='upgrade'?'强化一张卡牌':kind==='remove'?'移除一张卡牌':'当前牌组';openModal(title,`<p class="fine-print">${kind==='upgrade'?'选择卡牌完成强化，本次营地只可操作一次。强化后提高的数值显示在卡面上。':kind==='remove'?'选择不再需要的卡牌，将它从本局牌组中移除。':'战斗中的临时效果不改变这里的基础卡牌。'}</p><div class="card-library">${run.deck.map((c,i)=>kind==='upgrade'&&c.up?card(c,{small:true}):card(kind==='upgrade'?{...c,up:true}:c,{action:kind==='view'?'':kind==='upgrade'?'pick-upgrade':'pick-remove',index:i,small:true})).join('')}</div>`,true);}
function download(name,content,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportJSON(){if(!records.length)return toast('还没有记录。先完成一局游戏吧。');download('rogue-lab-records.json',JSON.stringify({schema:'rogue-lab-v1',exportedAt:new Date().toISOString(),note:'本机游戏记录；同一浏览器可能包含同一人的多次游玩，不代表独立玩家样本。',runs:records},null,2),'application/json');}
function exportCSV(){if(!records.length)return toast('还没有记录。先完成一局游戏吧。');const rows=[['id','version','mode','seed','result','stage','turns','cardsPlayed','damageTaken','durationSeconds','fairness','agency','enjoyment'],...records.map(r=>[r.id,r.version,r.mode,r.seed,r.result,r.stage+1,r.stats.turns,r.stats.cardsPlayed,r.stats.damageTaken,Math.round(r.durationMs/1000),r.rating?.fairness??'',r.rating?.agency??'',r.rating?.enjoyment??''])];const cell=v=>{let s=String(v);if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};download('rogue-lab-records.csv','\ufeff'+rows.map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
const actions={
 'filter':el=>{filter=el.dataset.filter;$('.filter.active')?.classList.remove('active');document.querySelectorAll('.filter').forEach(b=>b.setAttribute('aria-pressed',String(b===el)));el.classList.add('active');$('#atlas-results').innerHTML=atlasResults();},
 'reset-filter':()=>{filter='全部';query='';render();},
 'new-seed':()=>{$('#seed-input').value='EMBER-'+Math.random().toString(36).slice(2,8).toUpperCase();},
 'resume':()=>goRun(),'guide':guide,
 'library':()=>openModal('余烬卡牌手册 · 21 种卡牌',`<p class="fine-print">脉冲斩、相位盾、引火组成初始牌组；其余 18 种为奖励卡牌。数值为未强化版本。</p><div class="card-library">${Object.keys(E.CARDS).map(id=>card({id,up:false},{small:true})).join('')}</div>`,true),
 'play':el=>{if(E.playCard(run,Number(el.dataset.index))){beep(440);update();}},
 'end-turn':()=>{if(E.endTurn(run)){beep(160);update();}},
 'reward':el=>{if(E.takeReward(run,Number(el.dataset.index))){beep(620);update();}},
 'advance':()=>{if(E.advance(run)){update();}},
 'event-repair':()=>{if(E.eventChoice(run,'repair'))update();},
 'event-risk':()=>{if(E.eventChoice(run,'risk'))update();},
 'event-remove':()=>picker('remove'),
 'rest':()=>{if(E.camp(run,'rest'))update();},
 'upgrade':()=>picker('upgrade'),
 'view-deck':()=>picker('view'),
 'pick-upgrade':el=>{if(E.camp(run,'upgrade',Number(el.dataset.index))){closeModal();update();}},
 'pick-remove':el=>{if(E.eventChoice(run,'remove',Number(el.dataset.index))){closeModal();update();}},
 'piles':()=>openModal('本场战斗的卡牌',`<p class="fine-print">抽牌堆按名称排列，隐藏实际抽牌顺序。弃牌堆用完会洗回抽牌堆；消耗堆下场战斗恢复。</p>${[['抽牌堆',run.draw],['弃牌堆',run.discard],['消耗堆',run.exhaust]].map(([title,a])=>`<h3>${title} · ${a.length}</h3><div class="pile-list">${a.length?[...a].sort((x,y)=>x.id.localeCompare(y.id)).map(c=>`<span>${h(E.cardData(c).name)}${c.up?'+':''}</span>`).join(''):'<span>暂无卡牌</span>'}</div>`).join('')}`),
 'sound':()=>{sound=!sound;beep();render();},
 'new-game':()=>{location.hash='/game';},
 'replay-other':()=>start(run.seed,run.mode==='choice'?'random':'choice'),
 'close-modal':closeModal,
 'export-json':exportJSON,'export-csv':exportCSV,
 'clear-records':()=>openModal('清除本机记录',`<p>这会删除当前浏览器中保存的历史局与评分。建议先导出 JSON。当前未完成旅程会保留。</p><div class="modal-actions"><button class="button button-ghost" data-act="close-modal">保留记录</button><button class="button danger-button" data-act="confirm-clear">确认清除历史记录</button></div>`),
 'confirm-clear':()=>{records=[];write('rogue-records-v1',[]);if(run?.phase==='ended'){run=null;write('rogue-run-v1',null);}closeModal();render();toast('本机历史记录已清除。');},
 'credits':()=>openModal('关于重构 ROGUE LAB',`<p>一个关于“随机与选择”的互动游戏设计项目，包含原创卡牌肉鸽《余烬协议》和十款真实游戏的机制图鉴。</p><p>使用 AI 协助进行资料整理、代码、原创图形与文档制作。真人试玩数据由实际体验产生；本站没有填充虚构实验结果。</p><p>数据仅保存在当前浏览器，不自动上传。图鉴名称及相关权利归原权利人所有。</p><a class="text-link" href="#/research" data-act="close-modal">查看完整项目与来源</a>`),
 'confirm-start':el=>{const seed=el.dataset.seed,mode=el.dataset.mode;E.abandon(run);saveRun();closeModal();start(seed,mode);}
};
document.addEventListener('click',e=>{if(e.target.closest('a.skip')){e.preventDefault();const main=$('#main');main?.setAttribute('tabindex','-1');main?.focus();return;}const el=e.target.closest('[data-act]');if(el&&!el.disabled){actions[el.dataset.act]?.(el);}else if(e.target.classList.contains('modal-backdrop'))closeModal();});
document.addEventListener('input',e=>{if(e.target.id==='game-search'){query=e.target.value;$('#atlas-results').innerHTML=atlasResults();}});
document.addEventListener('submit',e=>{if(e.target.id==='start-form'){e.preventDefault();const fd=new FormData(e.target),seed=String(fd.get('seed')).trim(),mode=String(fd.get('mode'));if(!seed)return toast('请填写世界种子。');if(run&&run.phase!=='ended'){openModal('开启新的旅程？',`<p>目前节点 ${run.stage+1}/7 的旅程将记为中止，随后开始新的一局。</p><div class="modal-actions"><button class="button button-ghost" data-act="close-modal">继续保留</button><button class="button" data-act="confirm-start" data-seed="${h(seed)}" data-mode="${h(mode)}">开启新旅程</button></div>`);}else start(seed,mode);}if(e.target.id==='rating-form'){e.preventDefault();const fd=new FormData(e.target);run.rating=Object.fromEntries(['fairness','agency','enjoyment'].map(k=>[k,Number(fd.get(k))]));update();toast('体验反馈已保存。');}});
document.addEventListener('keydown',e=>{if($('.modal')){if(e.key==='Escape'){e.preventDefault();closeModal();return;}if(e.key==='Tab'){const f=[...$('.modal').querySelectorAll('a[href],button:not(:disabled),input,select,textarea,[tabindex="0"]')];if(f.length){if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0].focus();}}}return;}if(['INPUT','TEXTAREA','SELECT','BUTTON','A'].includes(document.activeElement?.tagName))return;if(route()==='/game/play'&&run?.phase==='battle'){if(/^[1-9]$/.test(e.key)){e.preventDefault();actions.play({dataset:{index:Number(e.key)-1}});}else if(e.code==='Space'){e.preventDefault();actions['end-turn']();}}});
window.addEventListener('hashchange',()=>{closeModal();render();window.scrollTo(0,0);});
try{const response=await fetch('./data.json');if(!response.ok)throw new Error('资料加载失败');data=await response.json();const saved=read('rogue-run-v1',null);run=E.validRun(saved)?saved:null;records=read('rogue-records-v1',[]);if(!Array.isArray(records))records=[];records=records.filter(r=>E.validRun(r)&&r.phase==='ended'&&['win','loss','abandoned'].includes(r.result)).slice(-100);render();}catch(error){$('#app').innerHTML='<main class="empty-state"><h1>实验室暂时没有接通信号。</h1><p>请刷新页面，或检查网络连接。</p><button class="button" onclick="location.reload()">重新连接</button></main>';console.error(error);}

if (document.documentElement.dataset.hosting !== 'github-pages') fetch('./api/visit',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}',cache:'no-store'}).then(r=>{if(!r.ok)throw new Error('counter unavailable');return r.json();}).then(d=>{visitTotal=Number.isSafeInteger(d.total)?d.total:false;document.querySelectorAll('[data-visit-total]').forEach(n=>n.textContent=visitTotal===false?'暂不可用':visitTotal.toLocaleString('zh-CN'));}).catch(()=>{visitTotal=false;document.querySelectorAll('[data-visit-total]').forEach(n=>n.textContent='暂不可用');});
